// libghostty-vt-sys installs ghostty-vt-static.lib, but rustc on windows-gnu
// links libghostty-vt.a; alias it. Delete once fixed upstream.
fn main() {
    // App version metadata is generated by the launch/export build scripts.
    // The extension does not embed it; watching every repository file here
    // needlessly relinks this library after unrelated UI or documentation edits.
    let target = std::env::var("TARGET").unwrap_or_default();
    if target.contains("apple-darwin") {
        cc::Build::new()
            .cpp(true)
            .file("src/ime_shim.mm")
            .file("src/trackpad.mm")
            .file("src/process_signals.cpp")
            .file("src/clipboard_mime.mm")
            .file("src/chromium_gpu.mm")
            .file("src/desktop_blur.mm")
            .file("src/folder_services_macos.mm")
            .file("src/window_frame_macos.mm")
            .flag("-fobjc-arc")
            .flag("-mmacosx-version-min=11.0")
            .compile("graffitty-ime-shim");
        println!("cargo:rustc-link-lib=framework=AppKit");
        println!("cargo:rustc-link-lib=framework=UniformTypeIdentifiers");
        println!("cargo:rerun-if-changed=src/clipboard_mime.mm");
        println!("cargo:rustc-link-lib=framework=Foundation");
        println!("cargo:rustc-link-lib=framework=Metal");
        println!("cargo:rustc-link-lib=framework=IOSurface");
        println!("cargo:rerun-if-changed=src/chromium_gpu.mm");
        println!("cargo:rerun-if-changed=src/desktop_blur.mm");
        println!("cargo:rerun-if-changed=src/folder_services_macos.mm");
        println!("cargo:rerun-if-changed=src/window_frame_macos.mm");
        println!("cargo:rerun-if-changed=src/chromium_gpu.rs");
        println!("cargo:rerun-if-changed=../../../crates/transport/chromium-video/include/frame_protocol.h");
        println!("cargo:rerun-if-changed=src/ime_shim.mm");
        println!("cargo:rerun-if-changed=src/trackpad.mm");
        println!("cargo:rerun-if-changed=src/process_signals.cpp");
    }
    if target == "aarch64-apple-ios" {
        cc::Build::new()
            .file("src/ios_renderer.m")
            .file("src/clipboard_ios.m")
            .flag("-fobjc-arc")
            .flag("-Werror=unguarded-availability-new")
            .compile("graffitty-ios-renderer");
        println!("cargo:rustc-link-lib=framework=Metal");
        println!("cargo:rerun-if-changed=src/ios_renderer.m");
        println!("cargo:rustc-link-lib=framework=UIKit");
        println!("cargo:rerun-if-changed=src/clipboard_ios.m");
    }
    if target.contains("windows") || (target.contains("linux") && !target.contains("android")) {
        cc::Build::new()
            .cpp(true)
            .file("src/desktop_blur.cpp")
            .compile("graffitty-desktop-blur");
        println!("cargo:rerun-if-changed=src/desktop_blur.cpp");
        if target.contains("linux") {
            println!("cargo:rustc-link-lib=dl");
            let mut build = cc::Build::new();
            build
                .cpp(true)
                .file("src/chromium_gpu_linux.cpp")
                .flag("-std=c++20")
                .flag("-Wno-missing-field-initializers");
            if let Ok(include) = std::env::var("VULKAN_HEADERS") {
                build.include(include);
            }
            build.compile("graffitty-chromium-gpu");
            println!("cargo:rustc-link-lib=vulkan");
            println!("cargo:rerun-if-env-changed=VULKAN_HEADERS");
            println!("cargo:rerun-if-changed=src/chromium_gpu_linux.cpp");
            println!("cargo:rerun-if-changed=../../../crates/transport/chromium-video/include/linux_vulkan.h");
            println!("cargo:rerun-if-changed=../../../crates/transport/chromium-video/include/frame_protocol_linux.h");
        }
    }
    if !target.contains("windows") {
        return;
    }
    cc::Build::new()
        .cpp(true)
        .file("src/window_frame_windows.cpp")
        .compile("graffitty-window-frame");
    println!("cargo:rustc-link-lib=comctl32");
    println!("cargo:rustc-link-lib=dwmapi");
    println!("cargo:rustc-link-lib=user32");
    println!("cargo:rerun-if-changed=src/window_frame_windows.cpp");
    if target.ends_with("windows-msvc") {
        // Zig's Ghostty archive does not carry the CRT default-library
        // directives. A full DLL link (unlike cargo check) needs these for
        // memory/math routines and C++ exception support.
        let static_crt = std::env::var("CARGO_CFG_TARGET_FEATURE")
            .unwrap_or_default()
            .split(',')
            .any(|feature| feature == "crt-static");
        for library in if static_crt {
            ["libucrt", "libvcruntime"]
        } else {
            ["ucrt", "vcruntime"]
        } {
            println!("cargo:rustc-link-lib={library}");
        }
    }
    let Ok(include) = std::env::var("DEP_GHOSTTY_VT_INCLUDE") else {
        return;
    };
    let lib = std::path::Path::new(&include).parent().unwrap().join("lib");
    let src = lib.join("ghostty-vt-static.lib");
    let dst = lib.join("libghostty-vt.a");
    if src.exists() && !dst.exists() {
        let _ = std::fs::copy(&src, &dst);
    }
    println!("cargo:rustc-link-search=native={}", lib.display());
}
